    def draw(r0, r1, c0, c1, color):
        # Add a pair of nested frames, then repeat inside the untouched gap.
        n = r1 - r0 + 1
        if n <= 3 or c1 - c0 + 1 <= 3:
            return
        a, b, x, y = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        for c in range(x, y + 1):
            out[a][c] = color
            out[b][c] = color
        for r in range(a, b + 1):
            out[r][x] = color
            out[r][y] = color
        other = 5 if color == 2 else 2
        if n - 4 == 2 and (y - x + 1) == 2:
            for r in range(a + 1, b):
                for c in range(x + 1, y):
                    out[r][c] = other
            return
        # Second one-cell frame; the 3x3 remainder is the next recursive region.
        if n >= 5 and c1 - c0 + 1 >= 5:
            a2, b2, x2, y2 = r0 + 2, r1 - 2, c0 + 2, c1 - 2
            for c in range(x2, y2 + 1):
                out[a2][c] = other
                out[b2][c] = other
            for r in range(a2, b2 + 1):
