                out[r][y2] = other
            # Keep a one-cell blank moat before the next recursively drawn motif.
            if r1 - r0 + 1 > 6 and c1 - c0 + 1 > 6:
                draw(r0 + 3, r1 - 3, c0 + 3, c1 - 3, other)

    draw(top, bottom, left, right, 2)
    return out
