    def recurse(t, b, l, rr, color):
        h, w = b - t + 1, rr - l + 1
        if h <= 2 or w <= 2:
            return
        # Fill the inner area with this layer's color.
        for r in range(t + 1, b):
            for c in range(l + 1, rr):
                out[r][c] = color
        # A contrasting square border two cells in from this region.
        if h > 4 and w > 4:
